<script>
  // Show More FAQs toggle
  function toggleMoreFAQs() {
    const moreFaqs = document.getElementById('more-faqs');
    const btn = document.getElementById('show-more-faqs-btn');
    const icon = btn.querySelector('svg');
    const label = btn.querySelector('span');
    if (moreFaqs.classList.contains('hidden')) {
      moreFaqs.classList.remove('hidden');
      label.textContent = 'Show Less FAQs';
      icon.style.transform = 'rotate(180deg)';
    } else {
      moreFaqs.classList.add('hidden');
      label.textContent = 'Show More FAQs';
      icon.style.transform = 'rotate(0deg)';
    }
  }

  // FAQ toggle (matching villa page pattern)
  function toggleFAQ(btn) {
    const content = btn.nextElementSibling;
    const icon = btn.querySelector('svg');
    const isOpen = content.classList.contains('h-auto');
    // Close all
    document.querySelectorAll('.faq-content').forEach(c => {
      c.classList.remove('h-auto');
      c.classList.add('h-0', 'opacity-0');
      const i = c.previousElementSibling.querySelector('svg');
      if (i) i.style.transform = 'rotate(0deg)';
    });
    if (!isOpen) {
      content.classList.remove('h-0', 'opacity-0');
      content.classList.add('h-auto');
      content.style.opacity = '1';
      icon.style.transform = 'rotate(180deg)';
    }
  }

  // Testimonial slider
  (function () {
    const track = document.getElementById('testimonial-track');
    const prevBtn = document.getElementById('testimonial-prev');
    const nextBtn = document.getElementById('testimonial-next');
    if (!track || !prevBtn || !nextBtn) return;
    let idx = 0;
    function getVisible() {
      if (window.innerWidth >= 1024) return 3;
      if (window.innerWidth >= 768) return 2;
      return 1;
    }
    function getTotal() { return track.children.length; }
    function slide() {
      const pct = 100 / getVisible();
      track.style.transform = 'translateX(-' + (idx * pct) + '%)';
    }
    nextBtn.addEventListener('click', function () {
      const max = getTotal() - getVisible();
      idx = idx < max ? idx + 1 : 0;
      slide();
    });
    prevBtn.addEventListener('click', function () {
      const max = getTotal() - getVisible();
      idx = idx > 0 ? idx - 1 : max;
      slide();
    });
    // Auto-slide every 5 seconds
    setInterval(function () {
      const max = getTotal() - getVisible();
      idx = idx < max ? idx + 1 : 0;
      slide();
    }, 5000);
    window.addEventListener('resize', slide);
  })();
</script>
